-- F01 foundation schema. Generated by prisma migrate diff, plus hand-written parts marked "hand-written".
-- Runs as the owner role (DATABASE_MIGRATION_URL). The runtime role gcli_app must already exist.

-- hand-written: fail early with a clear message when the runtime role is missing
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gcli_app') THEN
    RAISE EXCEPTION 'Role gcli_app is missing. Create it before running migrations (see docker/postgres/init/01-roles.sql).';
  END IF;
END $$;

-- hand-written: every table the owner creates is usable (DML) by the runtime role
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO gcli_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO gcli_app;

-- hand-written: extensions used by search features (F05 and later)
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;

