-- hand-written: value constraints (varchar + CHECK instead of native enums, architecture section 6)
ALTER TABLE "organization" ADD CONSTRAINT "ck_organization_slot" CHECK ("slot_granularity_minutes" IN (5, 10, 15, 30));
ALTER TABLE "organization" ADD CONSTRAINT "ck_organization_cnpj" CHECK ("cnpj" ~ '^[0-9A-Z]{12}[0-9]{2}$');
ALTER TABLE "app_user" ADD CONSTRAINT "ck_app_user_role" CHECK ("role" IN ('ADMINISTRATOR', 'MANAGER', 'FRONT_DESK', 'PROFESSIONAL'));
ALTER TABLE "app_user" ADD CONSTRAINT "ck_app_user_status" CHECK ("status" IN ('ACTIVE', 'INACTIVE'));
ALTER TABLE "app_user" ADD CONSTRAINT "ck_app_user_email_lower" CHECK ("email" = lower("email"));
ALTER TABLE "invitation" ADD CONSTRAINT "ck_invitation_role" CHECK ("role" IN ('ADMINISTRATOR', 'MANAGER', 'FRONT_DESK', 'PROFESSIONAL'));
ALTER TABLE "invitation" ADD CONSTRAINT "ck_invitation_status" CHECK ("status" IN ('PENDING', 'ACCEPTED', 'REVOKED'));

-- hand-written: at most one pending invitation per email in an organization
CREATE UNIQUE INDEX "uq_invitation_pending_email" ON "invitation" ("organization_id", "email") WHERE "status" = 'PENDING';

-- hand-written: outbox polling index
CREATE INDEX "ix_outbox_pending" ON "outbox_message" ("created_at") WHERE "dispatched_at" IS NULL;

-- hand-written: pg-boss keeps its own tables in a schema owned by the runtime role
CREATE SCHEMA IF NOT EXISTS pgboss AUTHORIZATION gcli_app;
